import { api } from "./src/backend/api";
import type { CommerceEnv } from "./src/backend/types";
// Generated by the framework build; intentionally imported only by Wrangler.
// @ts-expect-error generated JavaScript entry has no declaration file
import storefront from "./.output/server/index.mjs";

export default {
  async fetch(request: Request, env: CommerceEnv, ctx: ExecutionContext): Promise<Response> {
    const path = new URL(request.url).pathname;
    if (path.startsWith("/api/")) return api(request, env);
    if (path.startsWith("/media/")) {
      const key = path.slice(7);
      if (!/^[a-f0-9-]+\.(png|jpg|webp)$/.test(key) || !env.MEDIA)
        return new Response("Not found", { status: 404 });
      const visible = await env.DB.prepare(
        "SELECT id FROM products WHERE status='active' AND EXISTS(SELECT 1 FROM json_each(images) WHERE json_extract(value,'$.url')=?) UNION ALL SELECT id FROM banners WHERE active=1 AND image_url=? LIMIT 1",
      )
        .bind(path, path)
        .first();
      if (!visible) return new Response("Not found", { status: 404 });
      const image = await env.MEDIA.get(key);
      if (!image) return new Response("Not found", { status: 404 });
      return new Response(image.body, {
        headers: {
          "Content-Type": image.httpMetadata?.contentType ?? "application/octet-stream",
          "X-Content-Type-Options": "nosniff",
          "Cache-Control": "public,max-age=3600",
        },
      });
    }
    const response = await storefront.fetch(request, env, ctx);
    const headers = new Headers(response.headers);
    headers.set("X-Content-Type-Options", "nosniff");
    headers.set("Referrer-Policy", "strict-origin-when-cross-origin");
    headers.set("Permissions-Policy", "camera=(), microphone=(), geolocation=()");
    headers.set(
      "Content-Security-Policy",
      "frame-ancestors 'none'; object-src 'none'; base-uri 'self'; form-action 'self'",
    );
    if (env.APP_ORIGIN.startsWith("https:"))
      headers.set("Strict-Transport-Security", "max-age=31536000");
    if (path === "/admin" || path === "/account" || path === "/checkout")
      headers.set("Cache-Control", "no-store");
    return new Response(response.body, { status: response.status, headers });
  },
} satisfies ExportedHandler<CommerceEnv>;
